{"summary": "Implement long_words to return, in original order, words whose length is strictly greater than n from either a sentence string or a list of words.", "files": {"solution.py": "'''Write a function to shortlist words that are longer than n from a given list of words.'''

import builtins


def long_words(n, str):
    '''Write a function to shortlist words that are longer than n from a given list of words.'''
    if isinstance(str, builtins.str):
        words = str.split()
    else:
        words = str
    return [word for word in words if len(word) > n]
